for eid in targets:
    e = exps.get(eid)
    if e:
        print(f'{eid}: status={e.get(\"status\")}, conclusion={e.get(\"conclusion\")}, metrics={e.get(\"metrics\", {})}')
    else:
        print(f'{eid}: NOT FOUND')

# Also check TEAL eval experiments for GSM8K metrics
for eid, e in exps.items():
    if 'qwen14b' in eid and 'teal' in eid and e.get('status') == 'DONE':
        m = e.get('metrics', {})
        if m and ('gsm8k' in str(m).lower() or 'gsm8k_exact_match' in m):
            print(f'{eid}: status={e[\"status\"]}, conclusion={e.get(\"conclusion\")}, metrics={m}')

# Check for qwen14b dense baseline
for eid, e in exps.items():
    if 'qwen14b' in eid and 'dense' in eid and e.get('status') == 'DONE':
        m = e.get('metrics', {})
        if m:
            print(f'{eid}: status={e[\"status\"]}, conclusion={e.get(\"conclusion\")}, metrics={m}')
"

